import React from "react";


function TicketCard({
    dispute,
    onResolve
}) {


    /*
        Format grade date
    */
    const formatDate = (
        dateString
    ) => {

        if (!dateString) {

            return "-";

        }


        const date =
            new Date(
                dateString +
                "T00:00:00"
            );


        return date.toLocaleDateString(
            "en-IN",
            {
                day: "2-digit",
                month: "short",
                year: "numeric"
            }
        );

    };


    /*
        Format created date
    */
    const formatCreatedDate = (
        dateString
    ) => {

        if (!dateString) {

            return "-";

        }


        const date =
            new Date(
                dateString
            );


        return date.toLocaleDateString(
            "en-IN",
            {
                day: "2-digit",
                month: "short",
                year: "numeric"
            }
        );

    };


    /*
        Resolve confirmation
    */
    const handleResolve = () => {

        const confirmed =
            window.confirm(
                "Are you sure you want to mark this dispute as resolved?"
            );


        if (confirmed) {

            onResolve(
                dispute.id
            );

        }

    };


    return (

        <div className="ticket">


            {/* Ticket top */}

            <div className="ticket-top">


                <div className="ticket-subject">

                    {dispute.subject}

                </div>


                <span
                    className={
                        `status ${
                            dispute.status.toLowerCase()
                        }`
                    }
                >

                    {dispute.status}

                </span>


            </div>


            {/* Ticket ID */}

            <div className="ticket-id">

                Ticket #{dispute.id}

            </div>


            {/* Ticket Details */}

            <div className="ticket-details">


                <div className="ticket-detail">

                    Grade Date

                    <strong>

                        {formatDate(
                            dispute.grade_date
                        )}

                    </strong>

                </div>


                <div className="ticket-detail">

                    Created

                    <strong>

                        {formatCreatedDate(
                            dispute.created_at
                        )}

                    </strong>

                </div>


            </div>


            {/* Reason */}

            <div className="ticket-reason">

                {dispute.reason}

            </div>


            {/* Resolve button */}

            {dispute.status === "Open" && (

                <button
                    className="resolve-button"
                    onClick={handleResolve}
                >

                    ✓ Mark as Resolved

                </button>

            )}


        </div>

    );

}


export default TicketCard;
